using System;using System.IO;using System.Linq;using Terraria;using Terraria.ID;using Terraria.ModLoader.IO;using KivotosMod.Content.Tablet.Mail;using KivotosMod.Content.Tablet.Delivery;
public sealed class MailRandom:Random {public bool Fail;public int SpecialRoll;public override int Next(int maxValue)=>maxValue==10?SpecialRoll:maxValue==2&&Fail?1:0;public override int Next(int min,int max)=>min;}
public static class MailProbe {
 static void Check(bool ok,string why){if(!ok)throw new Exception(why);}
 static TabletMailPlayer State(int index)=>Main.player[index].GetModPlayer<TabletMailPlayer>();
 static TabletMailWorld Fresh(bool eligible=false){Main.netMode=0;Main.player=new[]{new Player{whoAmI=0},new Player{whoAmI=1}};Main.rand=new MailRandom();Main.time=0;Main.dayTime=true;Main.invasionType=0;Main.bloodMoon=false;Main.raining=false;Main.windSpeedCurrent=0;TabletDeliveryOrderSystem.Orders.Clear();TabletDeliveryOrderSystem.Queued=0;var w=new TabletMailWorld();w.OnWorldLoad();foreach(var p in Main.player){var s=p.GetModPlayer<TabletMailPlayer>();s.Ready=true;s.PlayedTicks=90000;s.LastDailyStamp=int.MaxValue;if(eligible){s.Receive("story:0",0,TabletMailCatalog.StoryGifts(0));s.Receive("story:1",1,TabletMailCatalog.StoryGifts(1));}}return w;}
 static void Tick(TabletMailWorld w,int time,bool day=true){Main.time=day?time:time-54000;Main.dayTime=day;for(int i=0;i<60;i++)w.PostUpdateWorld();}
 public static void Run(){
 var world=Fresh();Tick(world,0);Check(State(0).HasStory(0)&&!State(0).HasStory(1),"Intro order");Tick(world,26999);Check(!State(0).HasStory(1),"Lunch early");Tick(world,27000);Check(State(0).HasStory(1),"Lunch missing");
 Tick(world,37800);Check(State(0).HasStory(2)&&State(1).HasStory(2),"Shared story dispatch");Tick(world,70200,false);Check(State(0).Letters.Count==3,"More than one random story per day");
 var tag=new TagCompound();world.SaveWorldData(tag);var reload=new TabletMailWorld();reload.OnWorldLoad();reload.LoadWorldData(tag);Tick(reload,72000,false);Check(State(0).Letters.Count==3,"World reload duplicated dispatch");
 world=Fresh(true);((MailRandom)Main.rand).Fail=true;Tick(world,37800);Check(!State(0).HasStory(2),"50 percent failure ignored");Tick(world,60000,false);Tick(world,0);Tick(world,37800);Check(State(0).HasStory(2),"Missed-day guarantee failed");
 world=Fresh(true);Main.bloodMoon=true;Tick(world,37800);Check(!State(0).HasStory(2),"Story delivered during event");Main.bloodMoon=false;Tick(world,37800);Check(State(0).HasStory(2),"Deferred story missing");
 world=Fresh(true);foreach(var p in Main.player){var s=p.GetModPlayer<TabletMailPlayer>();for(int i=2;i<=10;i++)if(i!=9)s.Receive("story:"+i,i,TabletMailCatalog.StoryGifts(i));}Tick(world,27000);Check(!State(0).HasStory(9),"Windy mail without wind");Main.windSpeedCurrent=.5f;Main.raining=true;Tick(world,27000);Check(!State(0).HasStory(9),"Windy mail in rain");Main.raining=false;Tick(world,27000);Check(State(0).HasStory(9),"Windy clear mail missing");
 Check(TabletMailWorld.RewardStamp(new DateTimeOffset(2026,10,30,19,59,59,TimeSpan.Zero))==20261030,"4am lower boundary");Check(TabletMailWorld.RewardStamp(new DateTimeOffset(2026,10,30,20,0,0,TimeSpan.Zero))==20261031,"4am reset boundary");
 world=Fresh(true);State(0).LastDailyStamp=0;Tick(world,0);Check(State(0).Letters.Count(e=>e.Template>=100)==1,"Real daily missing");Tick(world,1);Check(State(0).Letters.Count(e=>e.Template>=100)==1,"Real daily repeated");
 var s0=State(0);s0.Action("story:0",1);s0.Action("story:0",2);s0.Action("story:0",3);s0.Action("story:0",3);Check(TabletDeliveryOrderSystem.Queued==1,"Double claim queued duplicate");var intro=s0.Letters.First(e=>e.Id=="story:0");Check(intro.Read&&intro.Favorite&&intro.Claimed&&intro.Pending,"Claim state incorrect");Check(s0.Sorted.Last().Id==intro.Id,"Claimed favorite sorted above bright mail");
 var save=new TagCompound();s0.SaveData(save);var loaded=new TabletMailPlayer{Player=new Player()};loaded.LoadData(save);var pending=loaded.Letters.First(e=>e.Id==intro.Id);loaded.QueuePending(pending);Check(TabletDeliveryOrderSystem.Queued==2,"Saved pending gift not resumed");TabletDeliveryOrderSystem.Orders[pending.OrderId].Complete();Check(!pending.Pending,"Delivery completion not recorded");
 using(var stream=new MemoryStream()){using var writer=new BinaryWriter(stream);s0.Write(writer);stream.Position=0;var wire=new TabletMailPlayer{Player=new Player()};wire.Read(new BinaryReader(stream));Check(wire.Letters.Count==s0.Letters.Count&&wire.HasStory(0)&&wire.LastDailyStamp==s0.LastDailyStamp,"Network state roundtrip");}
 s0.ResetMailbox();Check(s0.Letters.Count==0&&s0.LastDailyStamp>0,"Reset must clear records but preserve daily date");
 for(int stage=0;stage<4;stage++){for(int i=0;i<50;i++){var gifts=TabletMailCatalog.DailyGifts(stage);Check(gifts.Count>=5&&gifts.Count<=6&&gifts[0].Stack>=3&&gifts[0].Stack<=7,"Daily reward shape");Check(gifts.All(g=>g.Type>0&&g.Stack>0),"Invalid reward");if(stage==3)Check(gifts.Count==6,"Moonlord special not guaranteed");}}
 ((MailRandom)Main.rand).SpecialRoll=9;Check(TabletMailCatalog.DailyGifts(0).Count==5,"Pre-moonlord non-special roll");
 ((MailRandom)Main.rand).SpecialRoll=0;Check(TabletMailCatalog.DailyGifts(0).Count==6,"Pre-moonlord 10-percent special roll");
 Main.netMode=2;var other=State(1);other.Ready=true;int oldCount=other.Letters.Count;
 using(var stream=new MemoryStream()){using var w=new BinaryWriter(stream);w.Write((byte)4);w.Write("");stream.Position=0;Main.player[1].Tool=false;TabletMailPlayer.HandleAction(new BinaryReader(stream),1);Check(other.Letters.Count==oldCount,"Reset without held tool");}
 using(var stream=new MemoryStream()){using var w=new BinaryWriter(stream);w.Write((byte)4);w.Write("");stream.Position=0;Main.player[1].Tool=true;TabletMailPlayer.HandleAction(new BinaryReader(stream),1);Check(other.Letters.Count==0,"Authorized reset rejected");}
 Console.WriteLine("PASS: production mail catalog/player/world: intro sequencing, exact noon boundary, shared one/day story, world save/reload,50%/guaranteed-next-day,event suppression,windy clear rule,4am date,real daily idempotency,claim replay,sort,player save/pending recovery,delivery callback,wire roundtrip,reset,200 reward pools (engine stubbed).");
 }
}
